import unittest
import submission


class TestLintAndSplitSummary(unittest.TestCase):
    def test_combinations(self):
        sources = [("print('ok')\n", 0), ("train_test_split(x, y)\nmodel.fit(data)\n", 2)]
        splits = [([3, 1], [5, 4], True), ([1, 2], [2, 3], False)]
        for source, count in sources:
            for train, test, valid in splits:
                with self.subTest(source=source, train=train, test=test):
                    self.assertEqual(
                        submission.lint_and_split_summary(source, train, test),
                        {"violations": count, "split_ok": valid},
                    )


if __name__ == "__main__":
    unittest.main()

import pandas as pd
import unittest
import submission


class TestMakeMonotonicDf(unittest.TestCase):
    def test_sorted(self):
        for times in ([3, 1, 2], [9], [-2, 5, -2, 0], [8, 7, 6, 5]):
            with self.subTest(times=times):
                frame = submission.make_monotonic_df(list(times))
                self.assertIsInstance(frame, pd.DataFrame)
                self.assertEqual(frame["time"].tolist(), sorted(times))


if __name__ == "__main__":
    unittest.main()

